        void Start(){try{verify=Array.IndexOf(Environment.GetCommandLineArgs(),"-nativeGameplayVerify")>=0||Environment.GetEnvironmentVariable("ROOMLAB_NATIVE_GAMEPLAY_VERIFY")=="1";Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=1;
                var bytes=File.ReadAllBytes(Path.Combine(Application.streamingAssetsPath,"RoomLabNative","latest-physics.json"));var data=NativeProjectLoader.LoadBytes(bytes,"json",new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve,AssetRoot=Path.Combine(Application.streamingAssetsPath,"RoomLabNative"),RequireAssets=true});Attach(new NativeMotion(data,rules:NativeGameplayRules.LatestPhysics));
                keyboard.Bind((int)KeyCode.E,MotionBinding.Interact);foreach(var k in new[]{KeyCode.A,KeyCode.LeftArrow})keyboard.Bind((int)k,MotionBinding.Left);foreach(var k in new[]{KeyCode.D,KeyCode.RightArrow})keyboard.Bind((int)k,MotionBinding.Right);foreach(var k in new[]{KeyCode.Space,KeyCode.W,KeyCode.UpArrow})keyboard.Bind((int)k,MotionBinding.Up|MotionBinding.Jump);foreach(var k in new[]{KeyCode.S,KeyCode.DownArrow})keyboard.Bind((int)k,MotionBinding.Down);foreach(var k in new[]{KeyCode.LeftShift,KeyCode.RightShift})keyboard.Bind((int)k,MotionBinding.Dash);
