        Transform Box(string name,MotionRect r,Color color,int order){var go=new GameObject(name);go.transform.SetParent(geometry);var sr=go.AddComponent<SpriteRenderer>();sr.sprite=sprite;sr.color=color;sr.sortingOrder=order;Place(go.transform,r);return go.transform;}
        void Place(Transform t,MotionRect r){t.position=new Vector3((float)((r.x+r.w/2)/32),(float)(Game.Room.Rows-(r.y+r.h/2)/32),0);t.localScale=new Vector3((float)r.w/32,(float)r.h/32,1);}
        void RebuildRoom(){if(geometry!=null)Destroy(geometry.gameObject);geometry=new GameObject("Native Room "+Game.Room.Id).transform;geometry.SetParent(transform);objects.Clear();movables.Clear();loadedRoom=Game.Room.Id;
            foreach(var t in Game.Room.Tiles)Box("Terrain",new MotionRect(null,t.X*32,t.Y*32,32,32),new Color(.16f,.26f,.36f),0);
            foreach(var z in Game.Room.Zones)Box("Temperature zone",new MotionRect(null,z.X*32,z.Y*32,z.W*32,z.H*32),new Color(.15f,.4f,.65f,.12f),-1);
            foreach(var e in Game.Room.Exits)Box("出口",new MotionRect(null,e.X*32,e.Y*32,e.W*32,e.H*32),new Color(.2f,.85f,.6f,.5f),1);
            foreach(var o in Game.Room.Objects){var r=Game.ObjectRect(o);if(o.ColliderShape=="pad")r.h=8;if(o.Type=="common.small"){r.x+=11;r.y+=11;r.w=r.h=10;}else if(o.Type=="common.coin"){r.x+=7;r.y+=7;r.w=r.h=18;}var t=Box(o.Id,r,ColorFor(o),2);objects[o.Id]=t.GetComponent<SpriteRenderer>();if(o.Type=="physics.rail"){var path=o.Parameters["path"] as JArray;if(path!=null){var rail=new GameObject("Rail path");rail.transform.SetParent(geometry);var line=rail.AddComponent<LineRenderer>();line.sharedMaterial=new Material(Shader.Find("Sprites/Default"));line.positionCount=path.Count;line.startWidth=line.endWidth=.06f;line.startColor=line.endColor=new Color(.7f,.45f,1);for(int i=0;i<path.Count;i++)line.SetPosition(i,new Vector3((float)path[i]["x"],(float)(Game.Room.Rows-(double)path[i]["y"]),0));}}}
            foreach(var b in Game.Room.Movables)movables[b.Id]=Box(b.Id,Game.MovableRect(b),new Color(.45f,.6f,.65f),2);
            actor=Box("Player",Game.Player.Rect,new Color(.25f,.95f,.8f),5);pursuer=Box("AI",new MotionRect(null,0,0,24,28),new Color(.95f,.3f,.4f),4);UpdateVisuals();}
        Color ColorFor(NativeObject o){switch(o.Type){case "common.spike":return new Color(.95f,.18f,.3f);case "common.coin":case "common.small":return new Color(1,.77f,.2f);case "common.collectible":return new Color(1,.45f,.8f);case "common.checkpoint":return Game.VisualState(o)=="active"?new Color(.4f,1,.6f):new Color(.55f,.7f,1);case "physics.ice":return Game.VisualState(o)=="cracked"?new Color(.45f,.7f,.85f):new Color(.65f,.9f,1);case "physics.thermal":return Game.TemperatureAt(o)=="hot"?new Color(1,.4f,.15f):new Color(.2f,.6f,1);case "physics.rail":return new Color(.65f,.4f,1);case "common.aiStart":return new Color(.95f,.4f,.3f);case "common.portalIn":case "common.portalOut":return new Color(.5f,.4f,1,.65f);default:return new Color(.9f,.7f,.3f);}}
        void UpdateVisuals(){Place(actor,Game.Player.Rect);pursuer.gameObject.SetActive(Game.AI.active);Place(pursuer,new MotionRect(null,Game.AI.x-12,Game.AI.y-14,24,28));foreach(var o in Game.Room.Objects){var sr=objects[o.Id];sr.enabled=!Game.Credited.Contains(Game.Room.Id+"/"+o.Id)&&(o.Type!="physics.ice"||Game.ObjectStates[o.Id].solid);sr.color=ColorFor(o);}foreach(var b in Game.Room.Movables)Place(movables[b.Id],Game.MovableRect(b));
            cameraView.rect=new Rect(0,0,1,Mathf.Max(.2f,(Screen.height-92f)/Screen.height));float aspect=(float)Screen.width/Math.Max(1,Screen.height-92);bool full=map||Game.Room.CameraMode=="room";float rows=(float)(full?Game.Room.Rows:Game.Room.CameraRows),cols=(float)(full?Game.Room.Cols:Game.Room.CameraCols);if(rows<=0)rows=18;if(cols<=0)cols=32;cameraView.orthographicSize=full?Mathf.Max(rows/2,cols/2/aspect):Mathf.Max(7.5f,rows/2);float halfY=cameraView.orthographicSize,halfX=halfY*aspect;float x=full?Game.Room.Cols/2f:Mathf.Clamp((float)(Game.Player.x/32),Mathf.Min(halfX,Game.Room.Cols/2f),Mathf.Max(Game.Room.Cols-halfX,Game.Room.Cols/2f));float y=full?Game.Room.Rows/2f:Mathf.Clamp((float)(Game.Room.Rows-Game.Player.y/32),Mathf.Min(halfY,Game.Room.Rows/2f),Mathf.Max(Game.Room.Rows-halfY,Game.Room.Rows/2f));cameraView.transform.position=new Vector3(x,y,-10);}
        void Update(){if(Game==null||error!=null)return;if(!verify){if(GameInput.WasPressedExact(KeyCode.Escape)){select=false;transition=false;Game.TogglePause();timeline.Reset();keyboard.DiscardEdges();}if(GameInput.WasPressedExact(KeyCode.M))map=!map;if(GameInput.WasPressedExact(KeyCode.R)){transition=false;select=false;Game.Retry();timeline.Reset();keyboard.DiscardEdges();}AdvanceInput(Time.unscaledDeltaTime);}if(loadedRoom!=Game.Room.Id)RebuildRoom();UpdateVisuals();}
        void OnApplicationFocus(bool focus){if(!focus&&Game!=null&&!verify){keyboard.Clear();timeline.LoseFocus(Game);}}
        void Resume(){select=transition=false;if(Game.Completed)Game.Mode="won";else if(Game.Mode=="paused")Game.TogglePause();timeline.Reset();keyboard.DiscardEdges();}
        void ShowRoomSelection(){select=true;transition=false;}
        void RetryCurrentRoom(){Game.Retry();Resume();}
        void AdvanceInput(double elapsed){if(keyboard.Overflowed){timeline.Advance(Game,1,default(MotionInput));keyboard.DiscardEdges();}if(Game.Mode!="playing"||Game.RespawnRemaining>0)keyboard.DiscardEdges();while(keyboard.TryRead(out var edge))timeline.Advance(Game,0,edge);timeline.Advance(Game,elapsed,keyboard.Held);}
        void OnGUI(){if(font!=null)GUI.skin.font=font;GUI.skin.label.fontSize=17;GUI.skin.button.fontSize=17;if(Game!=null&&(Event.current.type==EventType.KeyDown||Event.current.type==EventType.KeyUp)){keyboard.Apply((int)Event.current.keyCode,Event.current.type==EventType.KeyDown);if(Game.Mode!="playing"||Game.RespawnRemaining>0)keyboard.DiscardEdges();}GUI.Box(new Rect(0,0,Screen.width,92),"");if(error!=null){GUI.Label(new Rect(15,12,Screen.width-30,300),error);return;}if(Game==null)return;
            GUI.Label(new Rect(18,7,Screen.width-36,24),"ROOMLAB  /  "+Game.Room.Name+"     分数 "+Game.Score+"     TOKEN "+Game.Tokens+"     库存 "+Game.Charges+"/"+Game.PaidStockCap);GUI.Label(new Rect(18,34,Screen.width-36,24),"A/D 移动 · 空格/W 跳跃 · S 下蹲 · Shift 冲刺 · E 交互 · R 重试 · M 地图 · Esc 菜单");GUI.Label(new Rect(18,60,Screen.width-36,24),(Game.RespawnRemaining>0?"复活准备中…":Game.NearbyInteraction!=null?"按 E 操作："+Game.NearbyInteraction.Name:Game.Message)+"    "+(Game.AI.active?"AI 追逐中":"")+"   "+(Game.Player.freeDash?"免费冲刺可用":"免费冲刺已用"));
            if(Game.Mode=="playing")return;float w=Math.Min(620,Screen.width-40),x=(Screen.width-w)/2,y=120;GUILayout.BeginArea(new Rect(x,y,w,Screen.height-y-25),GUI.skin.box);GUILayout.Space(12);GUILayout.Label(Game.Mode=="won"?"通关！  +50,000":select?"选择关卡 / 替换导入 · "+(Game.Rules==NativeGameplayRules.LatestPhysics?"最新物理策划":"编辑器 2.5.5 兼容"):transition?"已到达下一房间 · "+transitionName:"游戏已暂停");GUILayout.Space(10);if(timeline.ProtectionPaused)GUILayout.Label(timeline.ProtectionReason);
            if(!select){if(Game.Mode!="won"&&GUILayout.Button(transition?"继续下一房":"继续游戏",GUILayout.Height(40)))Resume();if(GUILayout.Button("重试当前房间",GUILayout.Height(40)))RetryCurrentRoom();if(GUILayout.Button("返回选关",GUILayout.Height(40)))ShowRoomSelection();if(GUILayout.Button("退出游戏",GUILayout.Height(40)))Application.Quit();if(Game.Mode=="paused"){GUILayout.Space(8);bool dev=GUILayout.Toggle(Game.DeveloperEnabled,"开发者检查");bool health=GUILayout.Toggle(Game.LockHealth,"锁定生命");bool flight=GUILayout.Toggle(Game.DeveloperFlight,"自由飞行（不拾取、不触发出口）");if(dev!=Game.DeveloperEnabled||health!=Game.LockHealth||flight!=Game.DeveloperFlight)Game.SetDeveloperOptions(dev,health,flight);}}
            else{scroll=GUILayout.BeginScrollView(scroll,GUILayout.Height(Math.Min(330,Screen.height-360)));foreach(var c in Game.Project.Courses)foreach(var r in c.Rooms)if(GUILayout.Button(r.Name,GUILayout.Height(32))){Attach(new NativeMotion(Game.Project,c.Id,r.Id,Game.Rules));Resume();}GUILayout.EndScrollView();GUILayout.Label("导入编辑器 2.5.5 的 JSON / ZIP（失败会保留当前关卡）");importPath=GUILayout.TextField(importPath);if(GUILayout.Button("选择关卡文件并导入",GUILayout.Height(36))){string path=PickFile();if(!string.IsNullOrEmpty(path)){importPath=path;LoadProjectFile(path);}}if(GUILayout.Button("导入上方路径",GUILayout.Height(30)))LoadProjectFile(importPath);GUILayout.Label(importStatus);if(GUILayout.Button("返回游戏",GUILayout.Height(32)))Resume();}GUILayout.EndArea();}
