        [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)]sealed class OpenFileName{public int size=Marshal.SizeOf(typeof(OpenFileName));public IntPtr owner,instance;public string filter="RoomLab project\0*.json;*.zip\0All files\0*.*\0";public string customFilter;public int maxCustomFilter,filterIndex=1;public string file=new string('\0',32768);public int maxFile=32768;public string fileTitle;public int maxFileTitle;public string initialDir,title="导入 RoomLab 关卡";public int flags=0x00080000|0x00001000;public short fileOffset,fileExtension;public string defExt;public IntPtr custData,hook;public string templateName;public IntPtr reserved;public int reserved2,flagsEx;}
