        void VerifyProductionUI()
        {
            var original=Game;var originalRoom=loadedRoom;
            try{
                var finalRoom=Game.Course.Rooms.Find(r=>r.Exits.Exists(e=>!Game.Course.Connections.Exists(c=>c.FromRoomId==r.Id&&c.ExitId==e.Id)));
                Attach(new NativeMotion(original.Project,original.Course.Id,finalRoom.Id,original.Rules));var exit=finalRoom.Exits.Find(e=>!Game.Course.Connections.Exists(c=>c.FromRoomId==finalRoom.Id&&c.ExitId==e.Id));
                void ReachExit(){Game.SetDeveloperOptions(true,true,false);Game.Player.x=exit.X*32+4;Game.Player.y=exit.Y*32+4;Game.Player.vx=Game.Player.vy=0;Game.ExitCooldown=0;Game.Tick(0);}
                ReachExit();int awarded=Game.Score;if(Game.Mode!="won"||!Game.Completed)throw new Exception("UI test never completed");
                // These are the same methods invoked by the production buttons above.
                ShowRoomSelection();Resume();if(select||Game.Mode!="won")throw new Exception("Return from selection reopened completed game");Game.Tick(0);if(Game.Score!=awarded)throw new Exception("UI return stacked completion score");
                RetryCurrentRoom();if(Game.Mode!="playing"||Game.Completed||Game.Score!=0||Game.RespawnRemaining!=.5)throw new Exception("UI retry failed to restore pre-award checkpoint");Game.RespawnRemaining=0;ReachExit();if(Game.Score!=awarded)throw new Exception("UI retry stacked prior award");
                Attach(new NativeMotion(original.Project,original.Course.Id,finalRoom.Id,original.Rules));ReachExit();if(Game.Score!=awarded)throw new Exception("New session cannot complete normally");
                Attach(new NativeMotion(original.Project,rules:original.Rules));for(int i=0;i<65;i++){keyboard.Apply((int)KeyCode.LeftShift,true);keyboard.Apply((int)KeyCode.LeftShift,false);}if(!keyboard.Overflowed)throw new Exception("Overflow setup did not reach actual queue");
                AdvanceInput(0);if(Game.Mode!="paused"||!timeline.ProtectionPaused||string.IsNullOrEmpty(timeline.ProtectionReason)||keyboard.PendingEdges!=0||Game.Player.dashCount!=0)throw new Exception("Production input path silently dropped overflow");Resume();AdvanceInput(0);if(Game.Mode!="playing"||timeline.ProtectionPaused||Game.Player.dashCount!=0)throw new Exception("Overflow recovery replayed stale input");Debug.Log("NATIVE_GAMEPLAY_UI_REPAIR_PASS terminalSelectionReturn=true retry=true newSession=true overflow65Paused=true visibleReason=true staleReplay=false");
            }finally{Game=original;loadedRoom=originalRoom;select=transition=false;timeline.Reset();keyboard.Clear();}
        }
        IEnumerator Verify(){yield return null;try{if(Game.Project.RoomCount!=11||Game.Project.ConnectionCount!=10||!Game.Project.AssetsResolved)throw new Exception("Default package mismatch");int smoke=NativeGameplaySmokeChecks.Run(Game.Project);Debug.Log("NATIVE_GAMEPLAY_SMOKE_PASS checks="+smoke);foreach(var r in Game.Course.Rooms){var g=new NativeMotion(Game.Project,Game.Course.Id,r.Id);for(int i=0;i<120;i++)g.Tick(NativeMotion.Step);if(double.IsNaN(g.Player.x))throw new Exception("Invalid player");}VerifyProductionUI();Debug.Log("NATIVE_GAMEPLAY_PLAYER_PASS rooms=11 connections=10 assets=9 externalRuntime=false");}catch(Exception e){Debug.LogException(e);Finish(2);yield break;}yield return null;string[] args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-nativeEvidencePath");string output=at>=0?args[at+1]:Path.Combine(Application.dataPath,"../NativeEvidence");Directory.CreateDirectory(output);var rt=RenderTexture.GetTemporary(1280,800,24);cameraView.targetTexture=rt;cameraView.Render();RenderTexture.active=rt;var image=new Texture2D(1280,800,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,800),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,"native-gameplay.png"),image.EncodeToPNG());cameraView.targetTexture=null;RenderTexture.active=null;RenderTexture.ReleaseTemporary(rt);Destroy(image);File.WriteAllText(Path.Combine(output,"player-result.json"),"{\"rooms\":11,\"connections\":10,\"assets\":9,\"native\":true,\"captureIncludesGUI\":false}");Finish(0);}
